const jobRows = $('Read Job Application Sheet').all().map(i => i.json);
const refRows = $('Read Reference Sheet').all().map(i => i.json);
const _ctx = this;
const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const ADMIN_CHAT_ID = '8873019272';

const refByComp = {};
for (const r of refRows) {
  const c = String(r['Company'] || '').trim().toLowerCase();
  const ref = String(r['Reference'] || '').trim();
  const soc = String(r['Social Media of Reference'] || '').trim();
  if (c && (ref || soc)) {
    refByComp[c] = { ref, soc };
  }
}

const activeCompanies = [];
const seen = new Set();

for (let i = jobRows.length - 1; i >= 0; i--) {
  const r = jobRows[i];
  const comp = String(r['Company'] || '').trim();
  const title = String(r['Position - Title'] || '').trim();
  const sNo = String(r['S. No.'] || '').trim();
  if (!comp || !title) continue;
  const key = comp.toLowerCase();
  if (!seen.has(key)) {
    seen.add(key);
    const refInfo = refByComp[key] || {};
    activeCompanies.push({
      sNo,
      company: comp,
      role: title,
      reference: String(r['Reference'] || refInfo.ref || '').trim(),
      socialUrl: refInfo.soc || '',
      status: String(r['Status'] || r['Resume Status'] || 'Active').trim()
    });
  }
  if (activeCompanies.length >= 5) break;
}

const PlaybookCards = activeCompanies.map(c => {
  const comp = c.company;
  const role = c.role;
  const insider = c.reference ? c.reference.split(/[\/,\s]+/)[0] : '';
  const hiName = insider ? `Hi ${insider},` : `Hi,`;
  const searchUrl = c.socialUrl || `https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(comp + ' Analytics')}`;

  return {
    company: comp,
    role,
    sNo: c.sNo,
    insider: c.reference || 'Analytics Peer / HM',
    searchUrl,
    sentimentGuide: [
      `• 📊 *Analytical / Tech Post* (React 💡): _"Clean metric definitions upfront usually save more time than the pipeline build itself. Good read."_`,
      `• 🎯 *Milestone / Team Launch* (React 🎉): _"Congrats on shipping this—looks like a solid step forward for the team at ${comp}."_`,
      `• 🧭 *Serious / Industry Shift* (React ❤️/💡, *Never Witty*): _"Appreciate you sharing a candid perspective on this. Important takeaway."_`,
      `• 💬 *Light Observation* (React 👍): _"The gap between the dashboard request and the actual business question is always the real work."_`
    ].join('\n'),
    warmConnectNote: `${hiName} came across your profile while following ${comp}'s analytics work. I work in data modelling and BI (SQL, Python, Tableau) and would love to connect.`,
    casualSlideInMsg: `Thanks for connecting${insider ? ', ' + insider : ''}. I recently applied for the ${role} role at ${comp} and wanted to share my profile in case my background in data modelling and BI is a fit for this or upcoming openings. Either way, glad to be connected.`,
    cadenceRule: `Poised Cadence: Keep comments under 18 words. Often a single 💡 or 👍 reaction without text is enough. Never double-DM if unaccepted.`
  };
});

if (PlaybookCards.length > 0) {
  const top = PlaybookCards[0];
  const text =
    `🤝 *Poised LinkedIn Playbook — ${top.company} (#${top.sNo})*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `💼 *Role:* ${top.role}\n` +
    `👤 *Contact:* *${top.insider}*\n` +
    `🎭 *Style:* *Poised, Concise & Sentiment-Matched* _(Zero Fluff)_\n\n` +
    `1️⃣ *Match the Post's Sentiment (1 Short Sentence Max):*\n` +
    `${top.sentimentGuide}\n\n` +
    `2️⃣ *Day 0 Connection Note (30 words, calm & peer-level):*\n` +
    `\`${top.warmConnectNote}\`\n\n` +
    `3️⃣ *Day 2+ Referral / Applied Slide-In (Poised, no pressure):*\n` +
    `\`${top.casualSlideInMsg}\`\n\n` +
    `🛡️ *Rule:* _${top.cadenceRule}_\n` +
    `🔗 [Open LinkedIn Profile / Search](${top.searchUrl})`;

  const kb = [
    [{ text: '💬 Paste a Post -> Get Sentiment-Matched Reply', callback_data: 'cmd:post_reply' }]
  ];
  for (const other of PlaybookCards.slice(1, 4)) {
    kb.push([{ text: `🤝 Switch to ${other.company} (#${other.sNo})`, callback_data: `net_comp:${other.sNo}` }]);
  }
  kb.push([{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]);

  try {
    await _ctx.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        chat_id: ADMIN_CHAT_ID,
        text,
        parse_mode: 'Markdown',
        disable_web_page_preview: true,
        reply_markup: { inline_keyboard: kb }
      },
      json: true
    });
  } catch (e) {}
}

return [{ json: { ok: true, count: PlaybookCards.length, PlaybookCards } }];
